class CompactThrift:
    TYPE_STOP = 0
    TYPE_BOOL_TRUE = 1
    TYPE_BOOL_FALSE = 2
    TYPE_BYTE = 3
    TYPE_I16 = 4
    TYPE_I32 = 5
    TYPE_I64 = 6
    TYPE_DOUBLE = 7
    TYPE_BINARY = 8
    TYPE_LIST = 9
    TYPE_SET = 10
    TYPE_MAP = 11
    TYPE_STRUCT = 12

    def __init__(self, data):
        self.data = data
        self.pos = 0

    def read_byte(self):
        b = self.data[self.pos]
        self.pos += 1
        return b

    def read_varint(self):
        res = 0
        shift = 0
        while True:
            b = self.data[self.pos]
            self.pos += 1
            res |= (b & 0x7f) << shift
            if (b & 0x80) == 0:
                break
            shift += 7
        return res

    def read_zigzag(self):
        n = self.read_varint()
        return (n >> 1) ^ -(n & 1)

    def read_binary(self):
        length = self.read_varint()
        data = self.data[self.pos:self.pos+length]
        self.pos += length
        return data

    def read_struct(self):
        fields = {}
        last_id = 0
        while True:
            b = self.read_byte()
            if b == 0:
                break
            type_id = b & 0x0f
            modifier = (b >> 4) & 0x0f
            if modifier == 0:
                field_id = self.read_zigzag()
            else:
                field_id = last_id + modifier
            last_id = field_id

            val = self.read_value(type_id)
            fields[field_id] = val
        return fields

    def read_value(self, type_id):
        if type_id == self.TYPE_BOOL_TRUE:
            return True
        elif type_id == self.TYPE_BOOL_FALSE:
            return False
        elif type_id == self.TYPE_BYTE:
            return self.read_byte()
        elif type_id in (self.TYPE_I16, self.TYPE_I32, self.TYPE_I64):
            return self.read_zigzag()
        elif type_id == self.TYPE_DOUBLE:
            import struct
            val = struct.unpack('<d', self.data[self.pos:self.pos+8])[0]
            self.pos += 8
            return val
        elif type_id == self.TYPE_BINARY:
            return self.read_binary()
        elif type_id in (self.TYPE_LIST, self.TYPE_SET):
            b = self.read_byte()
            elem_type = b & 0x0f
            size = (b >> 4) & 0x0f
            if size == 15:
                size = self.read_varint()
            return [self.read_value(elem_type) for _ in range(size)]
        elif type_id == self.TYPE_MAP:
            size = self.read_varint()
            if size == 0:
                return {}
            b = self.read_byte()
            ktype, vtype = (b >> 4) & 0x0f, b & 0x0f
            res = {}
            for _ in range(size):
                k = self.read_value(ktype)
                v = self.read_value(vtype)
                res[k] = v
            return res
        elif type_id == self.TYPE_STRUCT:
            return self.read_struct()
        else:
            raise ValueError(f"Unknown type_id {type_id} at pos {self.pos}")

with open('assets/alltypes_plain.parquet', 'rb') as f:
    content = f.read()

footer_len = int.from_bytes(content[-8:-4], 'little')
footer_data = content[-8-footer_len:-8]

ct = CompactThrift(footer_data)
meta = ct.read_struct()

print("Parsed FileMetaData keys:", meta.keys())
print("Version:", meta.get(1))
print("Num Rows:", meta.get(3))
print("Created By:", meta.get(6))
print("Schema elements count:", len(meta.get(2, [])))
print("First Schema Element:", meta.get(2)[0])
print("Second Schema Element:", meta.get(2)[1])
print("Row groups count:", len(meta.get(4, [])))
