cat <<'EOF' > src/main.rs
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};

#[derive(Debug, Clone)]
pub enum ThriftValue {
    Bool(bool),
    Byte(i8),
    I16(i16),
    I32(i32),
    I64(i64),
    Double(f64),
    Binary(Vec<u8>),
    List { elem_type: u8, elems: Vec<ThriftValue> },
    Map { ktype: u8, vtype: u8, entries: Vec<(ThriftValue, ThriftValue)> },
    Struct(Vec<(i16, ThriftValue)>),
}

pub struct CompactThriftReader<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> CompactThriftReader<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self { data, pos: 0 }
    }

    pub fn read_byte(&mut self) -> Result<u8, String> {
        if self.pos >= self.data.len() {
            return Err("Unexpected EOF".into());
        }
        let b = self.data[self.pos];
        self.pos += 1;
        Ok(b)
    }

    pub fn read_varint_u64(&mut self) -> Result<u64, String> {
        let mut res = 0u64;
        let mut shift = 0;
        loop {
            let b = self.read_byte()?;
            res |= ((b & 0x7f) as u64) << shift;
            if (b & 0x80) == 0 {
                break;
            }
            shift += 7;
            if shift >= 64 {
                return Err("Varint too long".into());
            }
        }
        Ok(res)
    }

    pub fn read_zigzag(&mut self) -> Result<i64, String> {
        let n = self.read_varint_u64()?;
        Ok(((n >> 1) as i64) ^ (-((n & 1) as i64)))
    }

    pub fn read_binary(&mut self) -> Result<Vec<u8>, String> {
        let len = self.read_varint_u64()? as usize;
        if self.pos + len > self.data.len() {
            return Err("Binary slice out of bounds".into());
        }
        let bytes = self.data[self.pos..self.pos + len].to_vec();
        self.pos += len;
        Ok(bytes)
    }

    pub fn read_struct(&mut self) -> Result<Vec<(i16, ThriftValue)>, String> {
        let mut fields = Vec::new();
        let mut last_id = 0i16;
        loop {
            let b = self.read_byte()?;
            if b == 0 {
                break; // STOP
            }
            let type_id = b & 0x0f;
            let modifier = (b >> 4) & 0x0f;
            let field_id = if modifier == 0 {
                self.read_zigzag()? as i16
            } else {
                last_id + (modifier as i16)
            };
            last_id = field_id;
            let val = self.read_value(type_id)?;
            fields.push((field_id, val));
        }
        Ok(fields)
    }

    pub fn read_value(&mut self, type_id: u8) -> Result<ThriftValue, String> {
        match type_id {
            1 => Ok(ThriftValue::Bool(true)),
            2 => Ok(ThriftValue::Bool(false)),
            3 => Ok(ThriftValue::Byte(self.read_byte()? as i8)),
            4 => Ok(ThriftValue::I16(self.read_zigzag()? as i16)),
            5 => Ok(ThriftValue::I32(self.read_zigzag()? as i32)),
            6 => Ok(ThriftValue::I64(self.read_zigzag()?)),
            7 => {
                if self.pos + 8 > self.data.len() {
                    return Err("EOF reading double".into());
                }
                let mut bytes = [0u8; 8];
                bytes.copy_from_slice(&self.data[self.pos..self.pos + 8]);
                self.pos += 8;
                Ok(ThriftValue::Double(f64::from_le_bytes(bytes)))
            }
            8 => Ok(ThriftValue::Binary(self.read_binary()?)),
            9 | 10 => {
                let header = self.read_byte()?;
                let elem_type = header & 0x0f;
                let mut size = ((header >> 4) & 0x0f) as usize;
                if size == 15 {
                    size = self.read_varint_u64()? as usize;
                }
                let mut elems = Vec::with_capacity(size);
                for _ in 0..size {
                    elems.push(self.read_value(elem_type)?);
                }
                Ok(ThriftValue::List { elem_type, elems })
            }
            11 => {
                let size = self.read_varint_u64()? as usize;
                if size == 0 {
                    return Ok(ThriftValue::Map { ktype: 0, vtype: 0, entries: vec![] });
                }
                let header = self.read_byte()?;
                let ktype = (header >> 4) & 0x0f;
                let vtype = header & 0x0f;
                let mut entries = Vec::with_capacity(size);
                for _ in 0..size {
                    let k = self.read_value(ktype)?;
                    let v = self.read_value(vtype)?;
                    entries.push((k, v));
                }
                Ok(ThriftValue::Map { ktype, vtype, entries })
            }
            12 => Ok(ThriftValue::Struct(self.read_struct()?)),
            _ => Err(format!("Unknown thrift type id {}", type_id)),
        }
    }
}

fn main() {
    let mut file = File::open("/workspace/assets/alltypes_plain.parquet").unwrap();
    let mut data = Vec::new();
    file.read_to_end(&mut data).unwrap();

    let footer_len = u32::from_le_bytes(data[data.len() - 8..data.len() - 4].try_into().unwrap()) as usize;
    let footer_data = &data[data.len() - 8 - footer_len..data.len() - 8];

    let mut reader = CompactThriftReader::new(footer_data);
    let meta_struct = reader.read_struct().unwrap();

    println!("FileMetaData fields count: {}", meta_struct.len());
    for (id, val) in &meta_struct {
        println!("  Field ID {}: {:?}", id, match val {
            ThriftValue::I32(i) => format!("I32({})", i),
            ThriftValue::I64(i) => format!("I64({})", i),
            ThriftValue::Binary(b) => format!("Binary({:?})", String::from_utf8_lossy(b)),
            ThriftValue::List { elems, .. } => format!("List(len={})", elems.len()),
            _ => format!("{:?}", val),
        });
    }
}
