use std::collections::{BTreeMap, BTreeSet};
use crate::thrift::{CompactThriftReader, ThriftValue};

#[derive(Debug, Clone)]
pub struct SchemaElement {
    pub name: String,
    pub type_: Option<i32>,
    pub type_length: Option<i32>,
    pub repetition_type: Option<i32>, // 0: REQUIRED, 1: OPTIONAL, 2: REPEATED
    pub num_children: Option<i32>,
    pub converted_type: Option<i32>,
    pub scale: Option<i32>,
    pub precision: Option<i32>,
}

impl SchemaElement {
    pub fn from_thrift(tv: &ThriftValue) -> Self {
        let name = tv.get_field(4).and_then(|v| v.as_string()).unwrap_or_default();
        let type_ = tv.get_field(1).and_then(|v| v.as_i32());
        let type_length = tv.get_field(2).and_then(|v| v.as_i32());
        let repetition_type = tv.get_field(3).and_then(|v| v.as_i32());
        let num_children = tv.get_field(5).and_then(|v| v.as_i32());
        let converted_type = tv.get_field(6).and_then(|v| v.as_i32());
        let scale = tv.get_field(7).and_then(|v| v.as_i32());
        let precision = tv.get_field(8).and_then(|v| v.as_i32());
        Self {
            name,
            type_,
            type_length,
            repetition_type,
            num_children,
            converted_type,
            scale,
            precision,
        }
    }

    pub fn repetition_str(&self) -> &'static str {
        match self.repetition_type {
            Some(0) => "REQUIRED",
            Some(1) => "OPTIONAL",
            Some(2) => "REPEATED",
            _ => "UNKNOWN",
        }
    }

    pub fn physical_type_str(&self) -> &'static str {
        match self.type_ {
            Some(0) => "BOOLEAN",
            Some(1) => "INT32",
            Some(2) => "INT64",
            Some(3) => "INT96",
            Some(4) => "FLOAT",
            Some(5) => "DOUBLE",
            Some(6) => "BYTE_ARRAY",
            Some(7) => "FIXED_LEN_BYTE_ARRAY",
            _ => "",
        }
    }
}

#[derive(Debug, Clone)]
pub struct SchemaNode {
    pub name: String,
    pub is_root: bool,
    pub type_: Option<i32>,
    pub type_length: Option<i32>,
    pub repetition_type: Option<i32>,
    pub converted_type: Option<i32>,
    pub children: Vec<SchemaNode>,
    pub leaf_index: Option<usize>,
    pub path: Vec<String>,
}

impl SchemaNode {
    pub fn build_tree(elements: &[SchemaElement]) -> (SchemaNode, Vec<usize>) {
        if elements.is_empty() {
            let root = SchemaNode {
                name: "root".to_string(),
                is_root: true,
                type_: None,
                type_length: None,
                repetition_type: None,
                converted_type: None,
                children: vec![],
                leaf_index: None,
                path: vec![],
            };
            return (root, vec![]);
        }

        let mut idx = 0;
        let mut leaf_counter = 0;
        let mut leaf_indices = Vec::new();

        fn parse_node(
            elements: &[SchemaElement],
            idx: &mut usize,
            leaf_counter: &mut usize,
            leaf_indices: &mut Vec<usize>,
            parent_path: Vec<String>,
        ) -> SchemaNode {
            let elem = &elements[*idx];
            *idx += 1;

            let mut current_path = parent_path;
            if *idx > 1 {
                current_path.push(elem.name.clone());
            }

            let num_children = elem.num_children.unwrap_or(0) as usize;
            let mut children = Vec::with_capacity(num_children);

            if num_children > 0 {
                for _ in 0..num_children {
                    if *idx < elements.len() {
                        let child = parse_node(elements, idx, leaf_counter, leaf_indices, current_path.clone());
                        children.push(child);
                    }
                }
                SchemaNode {
                    name: elem.name.clone(),
                    is_root: *idx == 1 || elem.name == "root",
                    type_: elem.type_,
                    type_length: elem.type_length,
                    repetition_type: elem.repetition_type,
                    converted_type: elem.converted_type,
                    children,
                    leaf_index: None,
                    path: current_path,
                }
            } else {
                let leaf_idx = *leaf_counter;
                *leaf_counter += 1;
                leaf_indices.push(leaf_idx);
                SchemaNode {
                    name: elem.name.clone(),
                    is_root: false,
                    type_: elem.type_,
                    type_length: elem.type_length,
                    repetition_type: elem.repetition_type,
                    converted_type: elem.converted_type,
                    children: vec![],
                    leaf_index: Some(leaf_idx),
                    path: current_path,
                }
            }
        }

        let root = parse_node(elements, &mut idx, &mut leaf_counter, &mut leaf_indices, vec![]);
        (root, leaf_indices)
    }

    pub fn flatten(&self) -> Vec<FlattenedSchemaItem> {
        let mut res = Vec::new();
        fn traverse(node: &SchemaNode, depth: usize, is_last: bool, prefix: &str, res: &mut Vec<FlattenedSchemaItem>) {
            let label = if node.is_root {
                "└─ root".to_string()
            } else {
                let connector = if is_last { "└─ " } else { "├─ " };
                format!("{}{}{}", prefix, connector, node.name)
            };

            res.push(FlattenedSchemaItem {
                node: node.clone(),
                depth,
                tree_label: label,
            });

            let child_prefix = if node.is_root {
                "   ".to_string()
            } else if is_last {
                format!("{}   ", prefix)
            } else {
                format!("{}│  ", prefix)
            };

            for (i, child) in node.children.iter().enumerate() {
                let last_child = i == node.children.len() - 1;
                traverse(child, depth + 1, last_child, &child_prefix, res);
            }
        }

        traverse(self, 0, true, "", &mut res);
        res
    }
}

#[derive(Debug, Clone)]
pub struct FlattenedSchemaItem {
    pub node: SchemaNode,
    pub depth: usize,
    pub tree_label: String,
}

#[derive(Debug, Clone)]
pub struct Statistics {
    pub max: Option<Vec<u8>>,
    pub min: Option<Vec<u8>>,
    pub null_count: Option<i64>,
    pub distinct_count: Option<i64>,
}

impl Statistics {
    pub fn from_thrift(tv: &ThriftValue) -> Self {
        Self {
            max: tv.get_field(1).and_then(|v| v.as_binary()).map(|b| b.to_vec()),
            min: tv.get_field(2).and_then(|v| v.as_binary()).map(|b| b.to_vec()),
            null_count: tv.get_field(3).and_then(|v| v.as_i64()),
            distinct_count: tv.get_field(4).and_then(|v| v.as_i64()),
        }
    }
}

#[derive(Debug, Clone)]
pub struct ColumnMetaData {
    pub type_: i32,
    pub encodings: Vec<i32>,
    pub path_in_schema: Vec<String>,
    pub codec: i32,
    pub num_values: i64,
    pub total_uncompressed_size: i64,
    pub total_compressed_size: i64,
    pub data_page_offset: i64,
    pub index_page_offset: Option<i64>,
    pub dictionary_page_offset: Option<i64>,
    pub statistics: Option<Statistics>,
    pub bloom_filter_offset: Option<i64>,
}

impl ColumnMetaData {
    pub fn from_thrift(tv: &ThriftValue) -> Self {
        let type_ = tv.get_field(1).and_then(|v| v.as_i32()).unwrap_or(0);
        let encodings = tv.get_field(2).and_then(|v| v.as_list()).map(|l| {
            l.iter().filter_map(|e| e.as_i32()).collect()
        }).unwrap_or_default();
        let path_in_schema = tv.get_field(3).and_then(|v| v.as_list()).map(|l| {
            l.iter().filter_map(|s| s.as_string()).collect()
        }).unwrap_or_default();
        let codec = tv.get_field(4).and_then(|v| v.as_i32()).unwrap_or(0);
        let num_values = tv.get_field(5).and_then(|v| v.as_i64()).unwrap_or(0);
        let total_uncompressed_size = tv.get_field(6).and_then(|v| v.as_i64()).unwrap_or(0);
        let total_compressed_size = tv.get_field(7).and_then(|v| v.as_i64()).unwrap_or(0);
        let data_page_offset = tv.get_field(9).and_then(|v| v.as_i64()).unwrap_or(0);
        let index_page_offset = tv.get_field(10).and_then(|v| v.as_i64());
        let dictionary_page_offset = tv.get_field(11).and_then(|v| v.as_i64());
        let statistics = tv.get_field(12).map(Statistics::from_thrift);
        let bloom_filter_offset = tv.get_field(14).and_then(|v| v.as_i64());

        Self {
            type_,
            encodings,
            path_in_schema,
            codec,
            num_values,
            total_uncompressed_size,
            total_compressed_size,
            data_page_offset,
            index_page_offset,
            dictionary_page_offset,
            statistics,
            bloom_filter_offset,
        }
    }

    pub fn codec_str(&self) -> &'static str {
        match self.codec {
            0 => "UNCOMPRESSED",
            1 => "SNAPPY",
            2 => "GZIP",
            3 => "LZO",
            4 => "BROTLI",
            5 => "LZ4",
            6 => "ZSTD(ZstdLevel(1))",
            7 => "LZ4_RAW",
            _ => "UNKNOWN",
        }
    }

    pub fn codec_short_str(&self) -> &'static str {
        match self.codec {
            0 => "UNCOMPR",
            1 => "SNAPPY",
            2 => "GZIP",
            3 => "LZO",
            4 => "BROTLI",
            5 => "LZ4",
            6 => "ZSTD",
            7 => "LZ4_RAW",
            _ => "UNKNOWN",
        }
    }
}

#[derive(Debug, Clone)]
pub struct ColumnChunk {
    pub file_path: Option<String>,
    pub file_offset: i64,
    pub meta_data: Option<ColumnMetaData>,
}

impl ColumnChunk {
    pub fn from_thrift(tv: &ThriftValue) -> Self {
        let file_path = tv.get_field(1).and_then(|v| v.as_string());
        let file_offset = tv.get_field(2).and_then(|v| v.as_i64()).unwrap_or(0);
        let meta_data = tv.get_field(3).map(ColumnMetaData::from_thrift);
        Self {
            file_path,
            file_offset,
            meta_data,
        }
    }
}

#[derive(Debug, Clone)]
pub struct RowGroup {
    pub columns: Vec<ColumnChunk>,
    pub total_byte_size: i64,
    pub num_rows: i64,
    pub total_compressed_size: Option<i64>,
}

impl RowGroup {
    pub fn from_thrift(tv: &ThriftValue) -> Self {
        let columns = tv.get_field(1).and_then(|v| v.as_list()).map(|l| {
            l.iter().map(ColumnChunk::from_thrift).collect()
        }).unwrap_or_default();
        let total_byte_size = tv.get_field(2).and_then(|v| v.as_i64()).unwrap_or(0);
        let num_rows = tv.get_field(3).and_then(|v| v.as_i64()).unwrap_or(0);
        let total_compressed_size = tv.get_field(6).and_then(|v| v.as_i64());
        Self {
            columns,
            total_byte_size,
            num_rows,
            total_compressed_size,
        }
    }
}

#[derive(Debug, Clone)]
pub struct FileMetaData {
    pub version: i32,
    pub schema: Vec<SchemaElement>,
    pub num_rows: i64,
    pub row_groups: Vec<RowGroup>,
    pub created_by: Option<String>,
}

impl FileMetaData {
    pub fn from_thrift(tv: &ThriftValue) -> Self {
        let version = tv.get_field(1).and_then(|v| v.as_i32()).unwrap_or(1);
        let schema = tv.get_field(2).and_then(|v| v.as_list()).map(|l| {
            l.iter().map(SchemaElement::from_thrift).collect()
        }).unwrap_or_default();
        let num_rows = tv.get_field(3).and_then(|v| v.as_i64()).unwrap_or(0);
        let row_groups = tv.get_field(4).and_then(|v| v.as_list()).map(|l| {
            l.iter().map(RowGroup::from_thrift).collect()
        }).unwrap_or_default();
        let created_by = tv.get_field(6).and_then(|v| v.as_string());
        Self {
            version,
            schema,
            num_rows,
            row_groups,
            created_by,
        }
    }
}

#[derive(Debug, Clone)]
pub struct PageInfo {
    pub page_num: usize,
    pub page_type: String,
    pub compressed_size: usize,
    pub uncompressed_size: usize,
    pub num_values: u32,
    pub encoding: String,
}

pub fn encoding_str(enc: i32) -> &'static str {
    match enc {
        0 => "PLAIN",
        1 => "PLAIN_DICTIONARY",
        2 => "RLE",
