pub fn decompress_snappy(src: &[u8]) -> Result<Vec<u8>, String> {
    let mut pos = 0;
    let mut uncompressed_len = 0usize;
    let mut shift = 0;
    loop {
        if pos >= src.len() { return Err("Invalid snappy header".into()); }
        let b = src[pos]; pos += 1;
        uncompressed_len |= ((b & 0x7f) as usize) << shift;
        if (b & 0x80) == 0 { break; }
        shift += 7;
    }
    let mut dst = Vec::with_capacity(uncompressed_len);
    while pos < src.len() && dst.len() < uncompressed_len {
        let tag_byte = src[pos]; pos += 1;
        let tag = tag_byte & 0x03;
        match tag {
            0 => {
                let mut len = ((tag_byte >> 2) as usize) + 1;
                if len > 60 {
                    let extra_bytes = len - 60;
                    len = 0;
                    for i in 0..extra_bytes {
                        if pos >= src.len() { break; }
                        len |= (src[pos] as usize) << (i * 8);
                        pos += 1;
                    }
                    len += 1;
                }
                if pos + len > src.len() {
                    let avail = src.len().saturating_sub(pos);
                    dst.extend_from_slice(&src[pos..pos + avail]);
                    break;
                }
                dst.extend_from_slice(&src[pos..pos + len]);
                pos += len;
            }
            1 => {
                let len = (((tag_byte >> 2) & 7) as usize) + 4;
                if pos >= src.len() { break; }
                let offset = (((tag_byte >> 5) as usize) << 8) | (src[pos] as usize);
                pos += 1;
                if offset == 0 { break; }
                for _ in 0..len {
                    if dst.len() >= offset {
                        let val = dst[dst.len() - offset];
                        dst.push(val);
                    }
                }
            }
            2 => {
                let len = ((tag_byte >> 2) as usize) + 1;
                if pos + 2 > src.len() { break; }
                let offset = (src[pos] as usize) | ((src[pos + 1] as usize) << 8);
                pos += 2;
                if offset == 0 { break; }
                for _ in 0..len {
                    if dst.len() >= offset {
                        let val = dst[dst.len() - offset];
                        dst.push(val);
                    }
                }
            }
            3 => {
                let len = ((tag_byte >> 2) as usize) + 1;
                if pos + 4 > src.len() { break; }
                let offset = (src[pos] as usize) | ((src[pos + 1] as usize) << 8) | ((src[pos + 2] as usize) << 16) | ((src[pos + 3] as usize) << 24);
                pos += 4;
                if offset == 0 { break; }
                for _ in 0..len {
                    if dst.len() >= offset {
                        let val = dst[dst.len() - offset];
                        dst.push(val);
                    }
                }
            }
            _ => unreachable!(),
        }
    }
    Ok(dst)
}

pub fn decompress_zstd(src: &[u8], uncompressed_size: usize) -> Result<Vec<u8>, String> {
    let mut dst = vec![0u8; uncompressed_size];
    let ret = unsafe { ZSTD_decompress(dst.as_mut_ptr(), dst.len(), src.as_ptr(), src.len()) };
    if ret > uncompressed_size * 2 {
        Err("Zstd decompression failed".into())
    } else {
        Ok(dst)
    }
}

pub fn decompress_page(codec: i32, src: &[u8], uncompressed_size: usize) -> Result<Vec<u8>, String> {
    match codec {
        0 => Ok(src.to_vec()),
        1 => decompress_snappy(src),
        2 => {
            let mut decoder = DeflateDecoder::new(src);
            let mut out = Vec::new();
            decoder.read_to_end(&mut out).map_err(|e| e.to_string())?;
            Ok(out)
        }
        6 => decompress_zstd(src, uncompressed_size),
        _ => Err(format!("Unsupported codec {}", codec)),
    }
}

pub struct ParquetFile {
    pub file_path: String,
    pub raw_data: Vec<u8>,
    pub file_meta: FileMetaData,
    pub schema_tree: SchemaNode,
    pub leaf_indices: Vec<usize>,
    pub columns_data: Vec<Vec<String>>,
    pub column_headers: Vec<String>,
}

impl ParquetFile {
    pub fn open<P: AsRef<Path>>(path: P) -> Result<Self, String> {
        let path_str = path.as_ref().to_string_lossy().to_string();
        let mut file = File::open(&path).map_err(|e| format!("No such file or directory (os error {})", e.raw_os_error().unwrap_or(2)))?;
        let mut raw_data = Vec::new();
        file.read_to_end(&mut raw_data).map_err(|e| e.to_string())?;

        if raw_data.len() < 12 || &raw_data[..4] != b"PAR1" || &raw_data[raw_data.len() - 4..] != b"PAR1" {
            return Err("Parquet error: Invalid Parquet file. Corrupt footer".to_string());
        }

        let footer_len = u32::from_le_bytes(raw_data[raw_data.len() - 8..raw_data.len() - 4].try_into().unwrap()) as usize;
        if raw_data.len() < 8 + footer_len {
            return Err("Parquet error: Invalid Parquet file. Corrupt footer".to_string());
        }

        let footer_data = &raw_data[raw_data.len() - 8 - footer_len..raw_data.len() - 8];
        let mut thrift_reader = CompactThriftReader::new(footer_data);
        let meta_tv = ThriftValue::Struct(thrift_reader.read_struct().map_err(|e| format!("Parquet error: Invalid Parquet file. {}", e))?);

        let file_meta = FileMetaData::from_thrift(&meta_tv);
        let (schema_tree, leaf_indices) = SchemaNode::build_tree(&file_meta.schema);

        let mut parquet_file = Self {
            file_path: path_str,
            raw_data,
            file_meta,
            schema_tree,
            leaf_indices,
            columns_data: vec![],
            column_headers: vec![],
        };

        parquet_file.load_visualize_data();
        Ok(parquet_file)
    }

    fn load_visualize_data(&mut self) {
        let mut headers = Vec::new();
        let mut col_data = Vec::new();

        let flattened = self.schema_tree.flatten();
        let mut root_children = Vec::new();
        for item in &flattened {
            if item.depth == 1 {
                root_children.push(&item.node);
            }
        }

        let num_rows = self.file_meta.num_rows as usize;

        for (c, child) in root_children.iter().enumerate() {
            headers.push(child.name.clone());

            let mut vals = Vec::with_capacity(num_rows);
            if let Some(col_chunk) = self.file_meta.row_groups.first().and_then(|rg| rg.columns.get(c)) {
                if let Some(ref meta) = col_chunk.meta_data {
                    vals = self.read_column_values(meta, child, num_rows);
                }
            }
            while vals.len() < num_rows {
                vals.push("NULL".to_string());
            }
            col_data.push(vals);
        }

        self.column_headers = headers;
        self.columns_data = col_data;
    }

    fn read_column_values(&self, meta: &ColumnMetaData, node: &SchemaNode, num_rows: usize) -> Vec<String> {
        let mut offset = meta.dictionary_page_offset.unwrap_or(meta.data_page_offset) as usize;
        let mut dict_strings: Vec<String> = Vec::new();
        let mut result = Vec::with_capacity(num_rows);

        while offset < self.raw_data.len() && result.len() < num_rows {
            let slice = &self.raw_data[offset..];
            let mut reader = CompactThriftReader::new(slice);
            let fields = match reader.read_struct() {
                Ok(f) => f,
                Err(_) => break,
            };
            let header_len = reader.pos();
            let header_tv = ThriftValue::Struct(fields);

            let page_type = header_tv.get_field(1).and_then(|v| v.as_i32()).unwrap_or(0);
            let uncomp_size = header_tv.get_field(2).and_then(|v| v.as_i32()).unwrap_or(0) as usize;
            let comp_size = header_tv.get_field(3).and_then(|v| v.as_i32()).unwrap_or(0) as usize;

            let page_bytes_start = offset + header_len;
            let page_bytes_end = (page_bytes_start + comp_size).min(self.raw_data.len());
            let comp_bytes = &self.raw_data[page_bytes_start..page_bytes_end];

            let page_buf = match decompress_page(meta.codec, comp_bytes, uncomp_size) {
                Ok(b) => b,
                Err(_) => break,
            };

            if page_type == 2 { // DICTIONARY_PAGE
                dict_strings = self.decode_plain_page(&page_buf, meta.type_, node, num_rows);
            } else if page_type == 0 || page_type == 3 { // DATA_PAGE / DATA_PAGE_V2
                let values = self.decode_data_page(&page_buf, page_type, &header_tv, meta, node, &dict_strings, num_rows - result.len());
                result.extend(values);
            }

            offset = page_bytes_start + comp_size;
        }

        while result.len() < num_rows {
            result.push("NULL".to_string());
        }
        result.truncate(num_rows);
        result
    }

    fn decode_plain_page(&self, buf: &[u8], physical_type: i32, node: &SchemaNode, count: usize) -> Vec<String> {
        let mut res = Vec::new();
        let mut pos = 0;
        for _ in 0..count {
            if pos >= buf.len() { break; }
            match physical_type {
                0 => { // BOOLEAN
                    res.push("false".to_string());
                }
                1 => { // INT32
                    if pos + 4 <= buf.len() {
                        let v = i32::from_le_bytes(buf[pos..pos+4].try_into().unwrap());
                        pos += 4;
                        res.push(v.to_string());
                    }
                }
                2 => { // INT64
                    if pos + 8 <= buf.len() {
                        let v = i64::from_le_bytes(buf[pos..pos+8].try_into().unwrap());
                        pos += 8;
                        res.push(v.to_string());
                    }
                }
                3 => { // INT96
                    if pos + 12 <= buf.len() {
                        let bytes: &[u8; 12] = buf[pos..pos+12].try_into().unwrap();
                        pos += 12;
                        res.push(format_int96_timestamp(bytes));
                    }
                }
                4 => { // FLOAT
                    if pos + 4 <= buf.len() {
                        let v = f32::from_le_bytes(buf[pos..pos+4].try_into().unwrap());
                        pos += 4;
                        if v.fract() == 0.0 {
                            res.push(format!("{:.1}", v));
                        } else {
                            res.push(format!("{}", v));
                        }
                    }
                }
                5 => { // DOUBLE
                    if pos + 8 <= buf.len() {
                        let v = f64::from_le_bytes(buf[pos..pos+8].try_into().unwrap());
                        pos += 8;
                        if v.fract() == 0.0 {
                            res.push(format!("{:.1}", v));
                        } else {
                            res.push(format!("{}", v));
                        }
                    }
                }
                6 => { // BYTE_ARRAY
                    if pos + 4 <= buf.len() {
                        let len = u32::from_le_bytes(buf[pos..pos+4].try_into().unwrap()) as usize;
                        pos += 4;
                        if pos + len <= buf.len() {
                            let bytes = &buf[pos..pos+len];
                            pos += len;
                            res.push(format_byte_array(bytes, node));
                        }
                    }
                }
                7 => { // FIXED_LEN_BYTE_ARRAY
                    let len = node.type_length.unwrap_or(0) as usize;
                    if len > 0 && pos + len <= buf.len() {
                        let bytes = &buf[pos..pos+len];
                        pos += len;
                        res.push(format_byte_array(bytes, node));
                    }
                }
                _ => break,
            }
        }
        res
    }

    fn decode_data_page(
        &self,
        buf: &[u8],
        page_type: i32,
        header_tv: &ThriftValue,
        meta: &ColumnMetaData,
        node: &SchemaNode,
        dict: &[String],
        max_rows: usize,
    ) -> Vec<String> {
        let num_values = if page_type == 0 {
            header_tv.get_field(5).and_then(|v| v.get_field(1)).and_then(|v| v.as_i32()).unwrap_or(0) as usize
        } else {
            header_tv.get_field(8).and_then(|v| v.get_field(1)).and_then(|v| v.as_i32()).unwrap_or(0) as usize
        };

        let mut pos = 0;

        // Skip repetition levels if REPEATED
        if node.repetition_type == Some(2) {
            if pos + 4 <= buf.len() {
                let rle_len = u32::from_le_bytes(buf[pos..pos+4].try_into().unwrap()) as usize;
                pos += 4 + rle_len;
            }
        }

        // Skip/read definition levels if OPTIONAL or REPEATED
        let mut def_levels = Vec::new();
        if node.repetition_type != Some(0) {
            if page_type == 0 {
                if pos + 4 <= buf.len() {
                    let def_len = u32::from_le_bytes(buf[pos..pos+4].try_into().unwrap()) as usize;
                    pos += 4;
                    if pos + def_len <= buf.len() {
                        def_levels = decode_rle_bitpacked(&buf[pos..pos+def_len], 1, num_values);
                        pos += def_len;
                    }
                }
            } else if page_type == 3 {
                let def_len = header_tv.get_field(8).and_then(|v| v.get_field(5)).and_then(|v| v.as_i32()).unwrap_or(0) as usize;
                if pos + def_len <= buf.len() {
                    def_levels = decode_rle_bitpacked(&buf[pos..pos+def_len], 1, num_values);
                    pos += def_len;
                }
            }
        }

        let value_bytes = if pos < buf.len() { &buf[pos..] } else { &[] };

        // If dict is present, decode dictionary indices
        if !dict.is_empty() && !value_bytes.is_empty() {
            let bit_width = value_bytes[0] as usize;
            let indices = decode_rle_bitpacked(&value_bytes[1..], bit_width, num_values);

            let mut res = Vec::with_capacity(num_values);
            let mut val_idx = 0;

            for i in 0..num_values {
                if !def_levels.is_empty() && i < def_levels.len() && def_levels[i] == 0 {
                    res.push("NULL".to_string());
                } else {
                    if val_idx < indices.len() {
                        let dict_idx = indices[val_idx] as usize;
                        val_idx += 1;
                        if dict_idx < dict.len() {
                            res.push(dict[dict_idx].clone());
                        } else {
                            res.push("NULL".to_string());
                        }
                    } else {
                        res.push("NULL".to_string());
                    }
                }
            }
            res.truncate(max_rows);
            return res;
        }

        // Plain decoding
        let plain_vals = self.decode_plain_page(value_bytes, meta.type_, node, num_values);
        let mut res = Vec::with_capacity(num_values);
        let mut val_idx = 0;

        for i in 0..num_values {
            if !def_levels.is_empty() && i < def_levels.len() && def_levels[i] == 0 {
                res.push("NULL".to_string());
            } else {
                if val_idx < plain_vals.len() {
                    res.push(plain_vals[val_idx].clone());
                    val_idx += 1;
                } else {
                    res.push("NULL".to_string());
                }
            }
        }

        res.truncate(max_rows);
        res
    }

    pub fn get_page_infos(&self, col_idx: usize) -> Vec<PageInfo> {
        let mut pages = Vec::new();
        if let Some(col_chunk) = self.file_meta.row_groups.first().and_then(|rg| rg.columns.get(col_idx)) {
            if let Some(ref meta) = col_chunk.meta_data {
                let mut start_offset = meta.dictionary_page_offset.unwrap_or(meta.data_page_offset) as usize;
                let end_offset = (meta.data_page_offset as usize + meta.total_compressed_size as usize).min(self.raw_data.len());

                let mut page_count = 1;
                while start_offset < end_offset && start_offset < self.raw_data.len() {
                    let slice = &self.raw_data[start_offset..];
                    let mut reader = CompactThriftReader::new(slice);
                    let fields = match reader.read_struct() {
                        Ok(f) => f,
                        Err(_) => break,
                    };
                    let header_len = reader.pos();
                    let header_tv = ThriftValue::Struct(fields);
                    let page_type_id = header_tv.get_field(1).and_then(|v| v.as_i32()).unwrap_or(0);
                    let uncomp_size = header_tv.get_field(2).and_then(|v| v.as_i32()).unwrap_or(0) as usize;
                    let comp_size = header_tv.get_field(3).and_then(|v| v.as_i32()).unwrap_or(0) as usize;

                    let mut num_values = 0u32;
                    let mut encoding_id = 0i32;

                    let page_type_name = match page_type_id {
                        0 => {
                            if let Some(dh) = header_tv.get_field(5) {
                                num_values = dh.get_field(1).and_then(|v| v.as_i32()).unwrap_or(0) as u32;
                                encoding_id = dh.get_field(2).and_then(|v| v.as_i32()).unwrap_or(0);
                            }
                            "Data Page"
                        }
                        2 => {
                            if let Some(dh) = header_tv.get_field(7) {
                                num_values = dh.get_field(1).and_then(|v| v.as_i32()).unwrap_or(0) as u32;
                                encoding_id = dh.get_field(2).and_then(|v| v.as_i32()).unwrap_or(0);
                            }
                            "Dictionary"
                        }
                        3 => {
                            if let Some(dh) = header_tv.get_field(8) {
                                num_values = dh.get_field(1).and_then(|v| v.as_i32()).unwrap_or(0) as u32;
                                encoding_id = dh.get_field(4).and_then(|v| v.as_i32()).unwrap_or(0);
                            }
                            "Data Page V2"
                        }
                        _ => "Data Page",
                    };

                    pages.push(PageInfo {
                        page_num: page_count,
                        page_type: page_type_name.to_string(),
                        compressed_size: comp_size,
                        uncompressed_size: uncomp_size,
                        num_values,
                        encoding: encoding_short_str(encoding_id).to_string(),
                    });

                    page_count += 1;
                    let next_offset = start_offset + header_len + comp_size;
                    if next_offset <= start_offset { break; }
                    start_offset = next_offset;
                }
            }
        }
        pages
    }
}

fn format_int96_timestamp(bytes: &[u8; 12]) -> String {
    let nanos = u64::from_le_bytes(bytes[0..8].try_into().unwrap());
    let julian_day = u32::from_le_bytes(bytes[8..12].try_into().unwrap());

    let epoch_day = (julian_day as i64) - 2440588;
    let secs = epoch_day * 86400 + (nanos / 1_000_000_000) as i64;
    let subsec_nanos = (nanos % 1_000_000_000) as u32;

    if let Some(dt) = chrono::DateTime::from_timestamp(secs, subsec_nanos) {
        dt.naive_utc().format("%Y-%m-%d %H:%M:%S").to_string()
    } else {
        format!("INT96({}, {})", nanos, julian_day)
    }
}

fn format_byte_array(bytes: &[u8], _node: &SchemaNode) -> String {
    if let Ok(s) = std::str::from_utf8(bytes) {
        format!("b\"{}\"", s)
    } else {
        format!("b\"{:?}\"", bytes)
    }
}

fn decode_rle_bitpacked(buf: &[u8], bit_width: usize, total_values: usize) -> Vec<u32> {
    let mut values = Vec::with_capacity(total_values);
    let mut pos = 0;

    while pos < buf.len() && values.len() < total_values {
        // read varint header
        let mut header = 0u64;
        let mut shift = 0;
        loop {
            if pos >= buf.len() { break; }
            let b = buf[pos]; pos += 1;
            header |= ((b & 0x7f) as u64) << shift;
            if (b & 0x80) == 0 { break; }
            shift += 7;
        }

        if (header & 1) == 0 {
            // RLE
            let count = (header >> 1) as usize;
            let num_bytes = (bit_width + 7) / 8;
            if num_bytes == 0 {
                values.extend(std::iter::repeat(0).take(count.min(total_values - values.len())));
                continue;
            }
            if pos + num_bytes > buf.len() { break; }
            let mut val = 0u32;
            for i in 0..num_bytes {
                val |= (buf[pos + i] as u32) << (i * 8);
            }
            pos += num_bytes;
            let mask = if bit_width == 32 { 0xffffffff } else { (1u32 << bit_width) - 1 };
            val &= mask;
            let take = count.min(total_values - values.len());
            values.extend(std::iter::repeat(val).take(take));
        } else {
            // Bit-packed
            let num_groups = (header >> 1) as usize;
            let count = num_groups * 8;
            let num_bytes = (count * bit_width + 7) / 8;
            if pos + num_bytes > buf.len() { break; }

            let packed_slice = &buf[pos..pos + num_bytes];
            pos += num_bytes;

            let mut bit_pos = 0;
            let mask = if bit_width == 32 { 0xffffffff } else { (1u32 << bit_width) - 1 };

            for _ in 0..count {
                if values.len() >= total_values { break; }
                let byte_idx = bit_pos / 8;
                let bit_offset = bit_pos % 8;

                let mut val = 0u64;
                for i in 0..5 {
                    if byte_idx + i < packed_slice.len() {
                        val |= (packed_slice[byte_idx + i] as u64) << (i * 8);
                    }
                }
                let value = ((val >> bit_offset) as u32) & mask;
                values.push(value);
                bit_pos += bit_width;
            }
        }
    }

    values
}
