use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use crate::reader::ParquetFile;

pub struct App {
    pub file: ParquetFile,
    pub active_tab: usize, // 0: Visualize, 1: Metadata, 2: Schema, 3: Row Groups
    pub running: bool,

    // Visualize tab state
    pub selected_row: usize,
    pub scroll_col: usize,

    // Schema tab state
    pub selected_schema_idx: usize,

    // Row Groups tab state
    pub current_rg_idx: usize,
    pub rg_selected_schema_idx: usize,
}

impl App {
    pub fn new(file: ParquetFile) -> Self {
        Self {
            file,
            active_tab: 0,
            running: true,
            selected_row: 0,
            scroll_col: 0,
            selected_schema_idx: 0,
            current_rg_idx: 0,
            rg_selected_schema_idx: 0,
        }
    }

    pub fn on_key(&mut self, key: KeyEvent, term_height: u16) {
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('Q') | KeyCode::Esc => {
                self.running = false;
                return;
            }
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.running = false;
                return;
            }
            KeyCode::Tab => {
                self.active_tab = (self.active_tab + 1) % 4;
                return;
            }
            KeyCode::BackTab => {
                self.active_tab = if self.active_tab == 0 { 3 } else { self.active_tab - 1 };
                return;
            }
            _ => {}
        }

        let num_rows = self.file.file_meta.num_rows as usize;
        let num_cols = self.file.column_headers.len();
        let flattened_schema = self.file.schema_tree.flatten();
        let num_schema_items = flattened_schema.len();
        let page_size = term_height.saturating_sub(6) as usize;

        match self.active_tab {
            0 => match key.code { // Visualize
                KeyCode::Up => {
                    self.selected_row = self.selected_row.saturating_sub(1);
                }
                KeyCode::Down => {
                    if num_rows > 0 && self.selected_row + 1 < num_rows {
                        self.selected_row += 1;
                    }
                }
                KeyCode::Left => {
                    self.scroll_col = self.scroll_col.saturating_sub(1);
                }
                KeyCode::Right => {
                    if num_cols > 0 && self.scroll_col + 1 < num_cols {
                        self.scroll_col += 1;
                    }
                }
                KeyCode::Char('u') | KeyCode::PageUp => {
                    self.selected_row = self.selected_row.saturating_sub(page_size);
                }
                KeyCode::Char('d') | KeyCode::PageDown => {
                    if num_rows > 0 {
                        self.selected_row = (self.selected_row + page_size).min(num_rows - 1);
                    }
                }
                _ => {}
            },
            1 => {}, // Metadata
            2 => match key.code { // Schema
                KeyCode::Up => {
                    self.selected_schema_idx = self.selected_schema_idx.saturating_sub(1);
                }
                KeyCode::Down => {
                    if num_schema_items > 0 && self.selected_schema_idx + 1 < num_schema_items {
                        self.selected_schema_idx += 1;
                    }
                }
                _ => {}
            },
            3 => match key.code { // Row Groups
                KeyCode::Up => {
                    self.rg_selected_schema_idx = self.rg_selected_schema_idx.saturating_sub(1);
                }
                KeyCode::Down => {
                    if num_schema_items > 0 && self.rg_selected_schema_idx + 1 < num_schema_items {
                        self.rg_selected_schema_idx += 1;
                    }
                }
                KeyCode::Right => {
                    let num_rgs = self.file.file_meta.row_groups.len();
                    if num_rgs > 0 {
                        self.current_rg_idx = (self.current_rg_idx + 1) % num_rgs;
                    }
                }
                KeyCode::Left => {
                    let num_rgs = self.file.file_meta.row_groups.len();
                    if num_rgs > 0 {
                        self.current_rg_idx = if self.current_rg_idx == 0 { num_rgs - 1 } else { self.current_rg_idx - 1 };
                    }
                }
                _ => {}
            },
            _ => {}
        }
    }
}
