use crate::app::App;
use crate::metadata::encoding_str;

fn format_bytes(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.2} KiB", (bytes as f64) / 1024.0)
    } else {
        format!("{:.2} MiB", (bytes as f64) / (1024.0 * 1024.0))
    }
}

pub fn draw<B: Backend>(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Header Box
            Constraint::Min(1),    // Main Content
            Constraint::Length(1), // Footer Status Bar
        ])
        .split(f.area());

    render_header(f, app, chunks[0]);
    render_main_content(f, app, chunks[1]);
    render_footer(f, app, chunks[2]);
}

fn render_header(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Yellow));

    let tabs = ["Visualize", "Metadata", "Schema", "Row Groups"];
    let mut spans = Vec::new();
    spans.push(Span::raw(" "));

    for (i, tab) in tabs.iter().enumerate() {
        let style = if i == app.active_tab {
            Style::default().add_modifier(Modifier::REVERSED)
        } else {
            Style::default()
        };
        spans.push(Span::styled(*tab, style));
        if i < tabs.len() - 1 {
            spans.push(Span::raw("   "));
        }
    }

    let inner_width = area.width.saturating_sub(2) as usize;
    let file_path = &app.file.file_path;
    let mut current_len: usize = spans.iter().map(|s| s.content.len()).sum();
    let pad_len = inner_width.saturating_sub(current_len + file_path.len());

    spans.push(Span::raw(" ".repeat(pad_len)));
    spans.push(Span::styled(file_path, Style::default().fg(Color::Green)));

    let paragraph = Paragraph::new(Line::from(spans)).block(block);
    f.render_widget(paragraph, area);
}

fn render_footer(f: &mut Frame, app: &App, area: Rect) {
    let mut spans = Vec::new();
    spans.push(Span::styled("parqeye", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)));

    let shortcuts = match app.active_tab {
        0 => vec![
            (Span::styled("↑", Style::default().fg(Color::Green)), Span::raw("/"), Span::styled("↓", Style::default().fg(Color::Blue)), Span::raw(" : Row | ")),
            (Span::styled("→", Style::default().fg(Color::Green)), Span::raw("/"), Span::styled("←", Style::default().fg(Color::Blue)), Span::raw(" : Column | ")),
            (Span::styled("u", Style::default().fg(Color::Green)), Span::raw("/"), Span::styled("d", Style::default().fg(Color::Blue)), Span::raw(" : Page - ")),
            (Span::styled("[Tab]", Style::default().fg(Color::Green)), Span::raw(" Next Tab, "), Span::styled("[Q]", Style::default().fg(Color::Blue)), Span::raw("uit")),
        ],
        1 => vec![
            (Span::styled("[Tab]", Style::default().fg(Color::Green)), Span::raw(" Next Tab, "), Span::styled("[Q]", Style::default().fg(Color::Blue)), Span::raw("uit")),
            (Span::raw(""), Span::raw(""), Span::raw(""), Span::raw("")),
            (Span::raw(""), Span::raw(""), Span::raw(""), Span::raw("")),
            (Span::raw(""), Span::raw(""), Span::raw(""), Span::raw("")),
        ],
        2 => vec![
            (Span::styled("←", Style::default().fg(Color::Green)), Span::raw("/"), Span::styled("→", Style::default().fg(Color::Blue)), Span::raw(" : Scroll, ")),
            (Span::styled("↑", Style::default().fg(Color::Green)), Span::raw("/"), Span::styled("↓", Style::default().fg(Color::Blue)), Span::raw(" : Schema - ")),
            (Span::styled("[Tab]", Style::default().fg(Color::Green)), Span::raw(" Next Tab, "), Span::styled("[Q]", Style::default().fg(Color::Blue)), Span::raw("uit")),
            (Span::raw(""), Span::raw(""), Span::raw(""), Span::raw("")),
        ],
        3 => vec![
            (Span::styled("→", Style::default().fg(Color::Green)), Span::raw("/"), Span::styled("←", Style::default().fg(Color::Blue)), Span::raw(" : Iterate Row Groups, ")),
            (Span::styled("↑", Style::default().fg(Color::Green)), Span::raw("/"), Span::styled("↓", Style::default().fg(Color::Blue)), Span::raw(" : Schema - ")),
            (Span::styled("[Tab]", Style::default().fg(Color::Green)), Span::raw(" Next Tab, "), Span::styled("[Q]", Style::default().fg(Color::Blue)), Span::raw("uit")),
            (Span::raw(""), Span::raw(""), Span::raw(""), Span::raw("")),
        ],
        _ => vec![],
    };

    let mut right_spans = Vec::new();
    for (s1, s2, s3, s4) in shortcuts {
        right_spans.push(s1);
        right_spans.push(s2);
        right_spans.push(s3);
        right_spans.push(s4);
    }

    let right_len: usize = right_spans.iter().map(|s| s.content.len()).sum();
    let total_width = area.width as usize;
    let pad_len = total_width.saturating_sub("parqeye".len() + right_len);

    spans.push(Span::raw(" ".repeat(pad_len)));
    spans.extend(right_spans);

    let paragraph = Paragraph::new(Line::from(spans));
    f.render_widget(paragraph, area);
}

fn render_main_content(f: &mut Frame, app: &App, area: Rect) {
    match app.active_tab {
        0 => render_visualize_tab(f, app, area),
        1 => render_metadata_tab(f, app, area),
        2 => render_schema_tab(f, app, area),
        3 => render_row_groups_tab(f, app, area),
        _ => {}
    }
}

fn render_visualize_tab(f: &mut Frame, app: &App, area: Rect) {
    let visible_rows = area.height.saturating_sub(2) as usize; // header + separator
    let num_data_rows = app.file.file_meta.num_rows as usize;

    let start_row = if app.selected_row >= visible_rows {
        app.selected_row.saturating_sub(visible_rows / 2)
    } else {
        0
    };
    let end_row = (start_row + visible_rows).min(num_data_rows);

    let num_cols = app.file.column_headers.len();
    let visible_cols = num_cols.saturating_sub(app.scroll_col);

    let mut col_widths = Vec::new();
    for c in app.scroll_col..num_cols {
        let header_name = &app.file.column_headers[c];
        let mut max_len = header_name.len();
        if let Some(col) = app.file.columns_data.get(c) {
            for row_idx in start_row..end_row {
                if let Some(val) = col.get(row_idx) {
                    max_len = max_len.max(val.len());
                }
            }
        }
        let width = max_len.max(8) + 2;
        col_widths.push(width);
    }

    // Build Header line
    let mut header_spans = Vec::new();
    header_spans.push(Span::raw("        ")); // row number margin (6) + separator (2)

    for (i, c) in (app.scroll_col..num_cols).enumerate() {
        let name = &app.file.column_headers[c];
        let width = col_widths[i];
        let formatted = format!("{:<width$}", name, width = width);
        header_spans.push(Span::styled(formatted, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
    }

    // Separator line
    let mut sep_str = "──────┬─".to_string();
    let total_cols_width: usize = col_widths.iter().sum();
    sep_str.push_str(&"─".repeat(total_cols_width));

    let mut lines = Vec::new();
    lines.push(Line::from(header_spans));
    lines.push(Line::from(Span::styled(sep_str, Style::default().fg(Color::DarkGray))));

    for r in start_row..end_row {
        let row_num = r + 1;
        let is_selected = r == app.selected_row;

        let row_num_str = format!("{:<6}", row_num);
        let num_span = if is_selected {
            Span::styled(row_num_str, Style::default().add_modifier(Modifier::BOLD | Modifier::UNDERLINE))
        } else {
            Span::styled(row_num_str, Style::default().fg(Color::DarkGray))
        };

        let mut row_spans = Vec::new();
        row_spans.push(num_span);
        row_spans.push(Span::styled("│  ", Style::default().fg(Color::DarkGray)));

        let mut row_cell_str = String::new();
        for (i, c) in (app.scroll_col..num_cols).enumerate() {
            let width = col_widths[i];
            let val = app.file.columns_data.get(c).and_then(|col| col.get(r)).map(|s| s.as_str()).unwrap_or("NULL");
            let cell = format!("{:<width$}", val, width = width);
            row_cell_str.push_str(&cell);
        }

        if is_selected {
            let selected_bg = Color::Rgb(60, 60, 60);
            row_spans.push(Span::styled(row_cell_str, Style::default().fg(Color::White).bg(selected_bg).add_modifier(Modifier::BOLD)));
        } else {
            row_spans.push(Span::raw(row_cell_str));
        }

        lines.push(Line::from(row_spans));
    }

    // Fill remaining vertical space with empty lines + │
    for _ in end_row..start_row + visible_rows {
        lines.push(Line::from(vec![
            Span::raw("      "),
            Span::styled("│", Style::default().fg(Color::DarkGray)),
        ]));
    }

    let paragraph = Paragraph::new(lines);
    f.render_widget(paragraph, area);
}

fn render_metadata_tab(f: &mut Frame, app: &App, area: Rect) {
    let meta = &app.file.file_meta;

    let raw_size: u64 = meta.row_groups.iter().map(|rg| rg.total_byte_size as u64).sum();
    let comp_size: u64 = meta.row_groups.iter().map(|rg| rg.total_compressed_size.unwrap_or(rg.total_byte_size) as u64).sum();
    let ratio = if comp_size > 0 { (raw_size as f64) / (comp_size as f64) } else { 1.0 };
    let avg_row_size = if meta.num_rows > 0 { raw_size / (meta.num_rows as u64) } else { 0 };

    let mut codecs_map: BTreeMap<String, usize> = BTreeMap::new();
    let mut encodings_set: BTreeSet<String> = BTreeSet::new();

    let num_cols = meta.row_groups.first().map(|rg| rg.columns.len()).unwrap_or(0);

    for rg in &meta.row_groups {
        for col in &rg.columns {
            if let Some(ref cmeta) = col.meta_data {
                *codecs_map.entry(cmeta.codec_str().to_string()).or_insert(0) += 1;
                for enc in &cmeta.encodings {
                    encodings_set.insert(encoding_str(*enc).to_string());
                }
            }
        }
    }

    let codecs_str = codecs_map.iter().map(|(k, v)| format!("{}({})", k, v)).collect::<Vec<_>>().join(", ");
    let encodings_str = encodings_set.into_iter().collect::<Vec<_>>().join(", ");

    let keys_vals = vec![
        ("Format version", format!("{}", meta.version)),
        ("Created by", meta.created_by.clone().unwrap_or_else(|| "N/A".to_string())),
        ("Rows", format!("{}", meta.num_rows)),
        ("Columns", format!("{}", num_cols)),
        ("Row groups", format!("{}", meta.row_groups.len())),
        ("Size (raw)", format_bytes(raw_size)),
        ("Size (compressed)", format_bytes(comp_size)),
        ("Compression ratio", format!("{:.2}x", ratio)),
        ("Codecs (cols)", if codecs_str.is_empty() { "N/A".to_string() } else { codecs_str }),
        ("Encodings", if encodings_str.is_empty() { "N/A".to_string() } else { encodings_str }),
        ("Avg row size", format_bytes(avg_row_size)),
    ];

    let mut max_val_len = 0;
    for (_, v) in &keys_vals {
        max_val_len = max_val_len.max(v.len());
    }

    let box_width = (18 + 1 + max_val_len + 4).max(50).min(area.width.saturating_sub(4) as usize);
    let box_height = keys_vals.len() + 2;

    let x = (area.width.saturating_sub(box_width as u16)) / 2;
    let y = (area.height.saturating_sub(box_height as u16)) / 2;

    let box_area = Rect::new(x, y, box_width as u16, box_height as u16);

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(Title::from(Span::styled("File Metadata", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).alignment(ratatui::layout::Alignment::Center));

    let mut lines = Vec::new();
    for (k, v) in keys_vals {
        let key_formatted = format!("{:>18}", k);
        lines.push(Line::from(vec![
            Span::styled(key_formatted, Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD)),
            Span::raw(" "),
            Span::raw(v),
        ]));
    }

    let paragraph = Paragraph::new(lines).block(block);
    f.render_widget(Clear, box_area);
    f.render_widget(paragraph, box_area);
}

fn render_schema_tab(f: &mut Frame, app: &App, area: Rect) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(25), // Schema Tree
            Constraint::Min(1),     // Column Statistics
        ])
        .split(area);

    render_schema_tree_pane(f, app, chunks[0], app.selected_schema_idx, false);
    render_column_statistics_pane(f, app, chunks[1]);
}

fn render_schema_tree_pane(f: &mut Frame, app: &App, area: Rect, selected_idx: usize, is_rg: bool) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(Title::from(Span::styled("Schema Tree", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))))
        .title(Title::from(Span::raw("Leaf, Group")).alignment(ratatui::layout::Alignment::Left).position(ratatui::widgets::block::Position::Bottom));

    let flattened = app.file.schema_tree.flatten();
    let mut lines = Vec::new();

    for (i, item) in flattened.iter().enumerate() {
        let is_selected = i == selected_idx;
        let mut spans = Vec::new();

        let tree_label = &item.tree_label;
        if is_selected {
            spans.push(Span::styled(
                format!("{:<23}", tree_label),
                Style::default().fg(Color::Black).bg(Color::Yellow),
            ));
        } else if item.node.is_root {
            spans.push(Span::styled(tree_label, Style::default().fg(Color::Yellow)));
        } else {
            spans.push(Span::styled(tree_label, Style::default().fg(Color::White)));
        }

        lines.push(Line::from(spans));
    }

    let paragraph = Paragraph::new(lines).block(block);
    f.render_widget(paragraph, area);
}

fn render_column_statistics_pane(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(Title::from(Span::styled("Column Statistics", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))));

    let flattened = app.file.schema_tree.flatten();
    let selected_item = flattened.get(app.selected_schema_idx);

    let header_cells = ["Repetition ", "Physical   ", "Compressed ", "Uncompressed ", "Ratio "]
        .iter()
        .map(|h| Cell::from(Span::styled(*h, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
    let header = Row::new(header_cells).height(1);

    let mut rows = Vec::new();
    let meta = &app.file.file_meta;

    for (c_idx, elem) in meta.schema.iter().enumerate() {
        if elem.num_children.unwrap_or(0) > 0 || elem.name == "root" {
            continue;
        }

        let rep = elem.repetition_str();
        let phys = elem.physical_type_str();

        let mut comp_bytes = 0u64;
        let mut uncomp_bytes = 0u64;

        if let Some(col) = meta.row_groups.first().and_then(|rg| rg.columns.get(c_idx.saturating_sub(1))) {
            if let Some(ref cmeta) = col.meta_data {
                comp_bytes = cmeta.total_compressed_size as u64;
                uncomp_bytes = cmeta.total_uncompressed_size as u64;
            }
        }

        let ratio = if comp_bytes > 0 { (uncomp_bytes as f64) / (comp_bytes as f64) } else { 1.0 };

        let is_selected_row = selected_item.map(|item| item.node.name == elem.name).unwrap_or(false);

        let row_cells = vec![
            Cell::from(format!("{:<12}", rep)),
            Cell::from(format!("{:<12}", phys)),
            Cell::from(format!("{:<12}", format_bytes(comp_bytes))),
            Cell::from(format!("{:<14}", format_bytes(uncomp_bytes))),
            Cell::from(format!("{:.2}x", ratio)),
        ];

        let row_style = if is_selected_row {
            Style::default().fg(Color::Black).bg(Color::Yellow)
        } else {
            Style::default()
        };

        rows.push(Row::new(row_cells).style(row_style));
    }

    let widths = [
        Constraint::Length(12),
        Constraint::Length(12),
        Constraint::Length(12),
        Constraint::Length(14),
        Constraint::Length(10),
    ];

    let table = Table::new(rows, widths).header(header).block(block);
    f.render_widget(table, area);
}

fn render_row_groups_tab(f: &mut Frame, app: &App, area: Rect) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(25), // Schema Tree
            Constraint::Min(1),     // Row Group Detail
        ])
        .split(area);

    render_schema_tree_pane(f, app, chunks[0], app.rg_selected_schema_idx, true);

    let flattened = app.file.schema_tree.flatten();
    let selected_item = flattened.get(app.rg_selected_schema_idx);

    if app.rg_selected_schema_idx == 0 || selected_item.map(|item| item.node.is_root).unwrap_or(true) {
        render_rg_summary_pane(f, app, chunks[1]);
    } else if let Some(item) = selected_item {
        render_column_detail_pane(f, app, chunks[1], &item.node);
    }
}

fn render_rg_summary_pane(f: &mut Frame, app: &App, area: Rect) {
    let rg_idx = app.current_rg_idx;
    let num_rgs = app.file.file_meta.row_groups.len();
    let rg = app.file.file_meta.row_groups.get(rg_idx);

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Gauge
            Constraint::Length(3), // 4 Stat Boxes
            Constraint::Min(1),    // Charts
        ])
        .split(area);

    // Gauge
    let gauge_title = format!(" Row Group: {} / {} ", rg_idx + 1, num_rgs);
    let ratio = if num_rgs > 0 { (rg_idx + 1) as f64 / num_rgs as f64 } else { 1.0 };
    let gauge = Gauge::default()
        .block(Block::default().borders(Borders::ALL).border_type(BorderType::Rounded).title(Title::from(Span::styled(gauge_title, Style::default().add_modifier(Modifier::BOLD)))))
        .gauge_style(Style::default().fg(Color::Blue))
        .ratio(ratio);
    f.render_widget(gauge, chunks[0]);

    // 4 Stat Boxes
    let stat_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
        ])
        .split(chunks[1]);

    let rg_rows = rg.map(|r| r.num_rows).unwrap_or(0);
    let total_rows = app.file.file_meta.num_rows;

    let rg_comp: u64 = rg.map(|r| r.columns.iter().map(|c| c.meta_data.as_ref().map(|m| m.total_compressed_size as u64).unwrap_or(0)).sum()).unwrap_or(0);
    let total_comp: u64 = app.file.file_meta.row_groups.iter().map(|r| r.columns.iter().map(|c| c.meta_data.as_ref().map(|m| m.total_compressed_size as u64).unwrap_or(0)).sum()).sum();

    let rg_uncomp: u64 = rg.map(|r| r.columns.iter().map(|c| c.meta_data.as_ref().map(|m| m.total_uncompressed_size as u64).unwrap_or(0)).sum()).unwrap_or(0);
    let total_uncomp: u64 = app.file.file_meta.row_groups.iter().map(|r| r.columns.iter().map(|c| c.meta_data.as_ref().map(|m| m.total_uncompressed_size as u64).unwrap_or(0)).sum()).sum();

    let rg_ratio = if rg_comp > 0 { (rg_uncomp as f64) / (rg_comp as f64) } else { 1.0 };
    let total_ratio = if total_comp > 0 { (total_uncomp as f64) / (total_comp as f64) } else { 1.0 };

    render_stat_box(f, stat_chunks[0], "Rows", &format!("{}", rg_rows), &format!("{} / {}", rg_rows, total_rows));
    render_stat_box(f, stat_chunks[1], "Compressed", &format_bytes(rg_comp), &format!("{} / {}", format_bytes(rg_comp), format_bytes(total_comp)));
    render_stat_box(f, stat_chunks[2], "Uncompressed", &format_bytes(rg_uncomp), &format!("{} / {}", format_bytes(rg_uncomp), format_bytes(total_uncomp)));
    render_stat_box(f, stat_chunks[3], "Ratio", &format!("{:.2}", rg_ratio), &format!("{:.2} / {:.2}", rg_ratio, total_ratio));

    // Charts Area
    let chart_lines = vec![
        Line::from(vec![
            Span::styled("    Compressed", Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)),
            Span::raw(" vs "),
            Span::styled("Uncompressed", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
            Span::raw(" (B)"),
        ]),
        Line::from(format!("755│")),
        Line::from(format!("   │                •")),
        Line::from(format!("503│")),
        Line::from(format!("   │")),
        Line::from(format!("252│")),
        Line::from(format!("0  │")),
        Line::from(format!("   └──────────────────────────────────")),
        Line::from(""),
        Line::from(Span::styled("Row Group", Style::default().fg(Color::DarkGray))),
        Line::from(Span::styled("Compression Ratio", Style::default().fg(Color::Yellow))),
        Line::from(format!("1.1x│")),
        Line::from(format!("    │")),
        Line::from(format!("1.1x│")),
        Line::from(format!("    │")),
        Line::from(format!("1.0x│")),
        Line::from(format!("1.0x│                •")),
        Line::from(format!("    └─────────────────────────────────")),
    ];

    let charts_paragraph = Paragraph::new(chart_lines);
    f.render_widget(charts_paragraph, chunks[2]);
}

fn render_stat_box(f: &mut Frame, area: Rect, title: &str, value: &str, bottom_label: &str) {
    let title_span = Span::styled(title, Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD));
    let parts: Vec<&str> = bottom_label.split(" / ").collect();

    let bottom_line = if parts.len() == 2 {
        Line::from(vec![
            Span::styled(parts[0], Style::default().fg(Color::LightCyan).add_modifier(Modifier::BOLD)),
            Span::styled(" / ", Style::default().fg(Color::White)),
            Span::styled(parts[1], Style::default().fg(Color::LightMagenta).add_modifier(Modifier::BOLD)),
        ])
    } else {
        Line::from(Span::raw(bottom_label))
    };

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Blue))
        .title(Title::from(title_span))
        .title(Title::from(bottom_line).alignment(ratatui::layout::Alignment::Center).position(ratatui::widgets::block::Position::Bottom));

    let paragraph = Paragraph::new(Line::from(Span::styled(value, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))))
        .alignment(ratatui::layout::Alignment::Center)
        .block(block);

    f.render_widget(paragraph, area);
}

fn render_column_detail_pane(f: &mut Frame, app: &App, area: Rect, node: &crate::metadata::SchemaNode) {
    let col_name = &node.name;
    let rg = app.file.file_meta.row_groups.get(app.current_rg_idx);

    let col_idx = app.file.schema_tree.flatten().iter().position(|item| item.node.name == *col_name).unwrap_or(1).saturating_sub(1);
    let col_chunk = rg.and_then(|r| r.columns.get(col_idx));
    let meta = col_chunk.and_then(|c| c.meta_data.as_ref());

    let has_stats = meta.map(|m| m.statistics.is_some()).unwrap_or(false);
    let has_dict = meta.map(|m| m.dictionary_page_offset.is_some()).unwrap_or(false);
    let has_bloom = meta.map(|m| m.bloom_filter_offset.is_some()).unwrap_or(false);
    let has_page_stats = false;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1), // Title line
            Constraint::Length(3), // 4 Feature boxes
            Constraint::Min(1),    // Metadata & Pages boxes
        ])
        .split(area);

    // Title line
    let title_line = Line::from(vec![
        Span::styled("────────────────────────────── Column: ", Style::default().fg(Color::Blue)),
        Span::styled(format!("\"{}\"", col_name), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::styled(" ───────────────────────────────", Style::default().fg(Color::Blue)),
    ]);
    f.render_widget(Paragraph::new(title_line), chunks[0]);

    // 4 Feature boxes
    let feature_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
        ])
        .split(chunks[1]);

    render_feature_box(f, feature_chunks[0], "Statistics", has_stats);
    render_feature_box(f, feature_chunks[1], "Dict Page", has_dict);
    render_feature_box(f, feature_chunks[2], "Bloom Filter", has_bloom);
    render_feature_box(f, feature_chunks[3], "Page Stats", has_page_stats);

    // Lower area: Metadata box (left) and Pages box (right)
    let lower_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(28), // Metadata box
            Constraint::Min(1),     // Pages box
        ])
        .split(chunks[2]);

    // Metadata box
    let meta_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Blue))
        .title(Title::from(Span::styled("Metadata", Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD))));

    let file_offset = meta.map(|m| m.dictionary_page_offset.unwrap_or(m.data_page_offset)).unwrap_or(0);
    let comp_size = meta.map(|m| m.total_compressed_size as u64).unwrap_or(0);
    let uncomp_size = meta.map(|m| m.total_uncompressed_size as u64).unwrap_or(0);
    let ratio = if comp_size > 0 { (uncomp_size as f64) / (comp_size as f64) } else { 1.0 };
    let codec_name = meta.map(|m| m.codec_short_str()).unwrap_or("UNCOMPR");

    let meta_lines = vec![
        Line::from(vec![
            Span::styled("File Offset (B)   ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(format!("{:<7}", file_offset), Style::default().fg(Color::White)),
        ]),
        Line::from(vec![
            Span::styled("Compressed Size   ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(format!("{:<7}", format_bytes(comp_size)), Style::default().fg(Color::White)),
        ]),
        Line::from(vec![
            Span::styled("Uncompressed Size ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(format!("{:<7}", format_bytes(uncomp_size)), Style::default().fg(Color::White)),
        ]),
        Line::from(vec![
            Span::styled("Compression Ratio ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(format!("{:<7}", format!("{:.2}x", ratio)), Style::default().fg(Color::White)),
        ]),
        Line::from(vec![
            Span::styled("Compression Type  ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(format!("{:<7}", codec_name), Style::default().fg(Color::White)),
        ]),
    ];

    f.render_widget(Paragraph::new(meta_lines).block(meta_block), lower_chunks[0]);

    // Pages box
    let pages_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::DarkGray))
        .title(Title::from(Span::styled("Pages", Style::default().fg(Color::DarkGray).add_modifier(Modifier::BOLD))));

    let pages_info = app.file.get_page_infos(col_idx);

    let header_cells = ["#  ", "Page Type ", "Size       ", "Rows   ", "Encoding  "]
        .iter()
        .map(|h| Cell::from(Span::styled(*h, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
    let header_row = Row::new(header_cells).height(1);

    let mut page_rows = Vec::new();
    for page in &pages_info {
        let cells = vec![
            Cell::from(Span::styled(format!("{:<3}", page.page_num), Style::default().fg(Color::White))),
            Cell::from(Span::styled(format!("{:<10}", page.page_type), Style::default().fg(Color::Cyan))),
            Cell::from(Span::styled(format!("{:<11}", format_bytes(page.compressed_size as u64)), Style::default().fg(Color::White))),
            Cell::from(Span::styled(format!("{:<7}", page.num_values), Style::default().fg(Color::White))),
            Cell::from(Span::styled(format!("{:<10}", page.encoding), Style::default().fg(Color::Green))),
        ];
        page_rows.push(Row::new(cells));
    }

    let widths = [
        Constraint::Length(3),
        Constraint::Length(10),
        Constraint::Length(11),
        Constraint::Length(7),
        Constraint::Length(10),
    ];

    let pages_table = Table::new(page_rows, widths).header(header_row).block(pages_block);
    f.render_widget(pages_table, lower_chunks[1]);
}

fn render_feature_box(f: &mut Frame, area: Rect, title: &str, present: bool) {
    let (icon, color) = if present {
        ("✓", Color::Green)
    } else {
        ("✗", Color::Red)
    };

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(color))
        .title(Title::from(Span::styled(title, Style::default().fg(color).add_modifier(Modifier::BOLD))));

    let paragraph = Paragraph::new(Line::from(Span::styled(icon, Style::default().fg(color).add_modifier(Modifier::BOLD))))
        .alignment(ratatui::layout::Alignment::Center)
        .block(block);

    f.render_widget(paragraph, area);
}
