mod reader;
mod app;
mod ui;

use std::env;
use std::io::stdout;
use std::panic;
use clap::{Arg, Command};

use crossterm::{
    event::{self, Event, KeyCode},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{backend::CrosstermBackend, Terminal};

use app::App;
use reader::ParquetFile;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let matches = Command::new("executable")
        .about("Command line tool to visualize parquet files")
        .version("0.0.2")
        .arg(
            Arg::new("PATH")
                .help("Path to the parquet file")
                .required(true)
                .index(1),
        )
        .get_matches();

    let path_str: &String = matches.get_one("PATH").unwrap();

    let parquet_file = match ParquetFile::open(path_str) {
        Ok(pf) => pf,
        Err(e) => {
            eprintln!("Error: Custom {{ kind: Other, error: \"{}\" }}", e);
            std::process::exit(1);
        }
    };

    // Setup panic hook to restore terminal
    let default_hook = panic::take_hook();
    panic::set_hook(Box::new(move |panic_info| {
        let _ = disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen);
        default_hook(panic_info);
    }));

    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(parquet_file);

    while app.running {
        terminal.draw(|f| ui::draw(f, &app))?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                let height = terminal.size()?.height;
                app.on_key(key, height);
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}
EOF
"}

